    ($SATQ$52b1700c$SATQ$, $SATQ$e78c85a7-41e7-485b-b784-99727df47183$SATQ$::uuid, $SATQ$c6a2416f-bd8d-4b20-921b-dfeaf4939e56$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Advanced Math$SATQ$, $SATQ$P$SATQ$, $SATQ$P.C.$SATQ$, $SATQ$Nonlinear functions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, NULL, $SATQ$<table style='border-collapse: collapse; width: 100%; border-color: #000000; border-style: solid; margin-left: auto; margin-right: auto;' border='1'>
